class Component extends DCLogic {
  state = {
    zoomOpen: false,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragOffsetStartX: 0,
    dragOffsetStartY: 0,
    zoomOpenB: false,
    scaleB: 1,
    offsetXB: 0,
    offsetYB: 0,
    draggingB: false,
    dragStartXB: 0,
    dragStartYB: 0,
    dragOffsetStartXB: 0,
    dragOffsetStartYB: 0
  };

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-dialog="colombia-cartagena-1-real-1813"] [data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  focusTrigger = () => {
    const trigger = document.querySelector('[data-zoom-trigger="colombia-cartagena-1-real-1813"]');
    if (trigger) trigger.focus();
  };

  openZoom = () => {
    this.setState({ zoomOpen: true, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomOpen: false });
    requestAnimationFrame(() => requestAnimationFrame(this.focusTrigger));
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  focusCloseB = () => {
    const closeBtn = document.querySelector('[data-zoom-dialog="colombia-papel-sellado-un-real-1821"] [data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusCloseB);
  };

  focusTriggerB = () => {
    const trigger = document.querySelector('[data-zoom-trigger="colombia-papel-sellado-un-real-1821"]');
    if (trigger) trigger.focus();
  };

  openZoomB = () => {
    this.setState({ zoomOpenB: true, scaleB: 1, offsetXB: 0, offsetYB: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusCloseB));
  };

  closeZoomB = () => {
    this.setState({ zoomOpenB: false });
    requestAnimationFrame(() => requestAnimationFrame(this.focusTriggerB));
  };

  zoomInB = () => this.setState(s => ({ scaleB: Math.min(4, Math.round((s.scaleB + 0.5) * 10) / 10) }));
  zoomOutB = () => this.setState(s => {
    const next = Math.max(1, Math.round((s.scaleB - 0.5) * 10) / 10);
    return { scaleB: next, offsetXB: next === 1 ? 0 : s.offsetXB, offsetYB: next === 1 ? 0 : s.offsetYB };
  });

  onWheelB = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scaleB + delta) * 100) / 100));
      return { scaleB: next, offsetXB: next === 1 ? 0 : s.offsetXB, offsetYB: next === 1 ? 0 : s.offsetYB };
    });
  };

  onPointerDownB = (e) => {
    if (this.state.scaleB <= 1) return;
    this.setState({ draggingB: true, dragStartXB: e.clientX, dragStartYB: e.clientY, dragOffsetStartXB: this.state.offsetXB, dragOffsetStartYB: this.state.offsetYB });
  };

  onPointerMoveB = (e) => {
    if (!this.state.draggingB) return;
    const dx = e.clientX - this.state.dragStartXB;
    const dy = e.clientY - this.state.dragStartYB;
    this.setState({ offsetXB: this.state.dragOffsetStartXB + dx, offsetYB: this.state.dragOffsetStartYB + dy });
  };

  onPointerUpB = () => this.setState({ draggingB: false });

  onKeyDown = (e) => {
    if (e.key !== "Escape") return;
    if (this.state.zoomOpen) this.closeZoom();
    if (this.state.zoomOpenB) this.closeZoomB();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    return {
      zoomOpen: s.zoomOpen,
      openZoom: this.openZoom,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",

      zoomOpenB: s.zoomOpenB,
      openZoomB: this.openZoomB,
      closeZoomB: this.closeZoomB,
      zoomInHandlerB: this.zoomInB,
      zoomOutHandlerB: this.zoomOutB,
      onWheelB: this.onWheelB,
      onPointerDownB: this.onPointerDownB,
      onPointerMoveB: this.onPointerMoveB,
      onPointerUpB: this.onPointerUpB,
      zoomInDisabledB: s.scaleB >= 4,
      zoomOutDisabledB: s.scaleB <= 1,
      zoomPercentB: Math.round(s.scaleB * 100) + "%",
      imgTransformB: `translate(${s.offsetXB}px, ${s.offsetYB}px) scale(${s.scaleB})`,
      imgCursorB: s.scaleB > 1 ? (s.draggingB ? "grabbing" : "grab") : "default"
    };
  }
}
